// trace_rustc_driver_main.rs - Trace rustc_driver::main (the real compiler)
// Generated by step4_bootstrap - Trace Real Compiler Entry Point

use split_decls_genesis::{extract_all_symbols_from_file_fast, resolve_qualified_dependency};
use std::collections::HashMap;
use serde_json;

fn main() {
    println!("🔍 Tracing rustc_driver::main (the REAL compiler entry point)...");
    
    // Load full symbol map
    let symbol_map_json: HashMap<String, serde_json::Value> = 
        serde_json::from_str(&std::fs::read_to_string("symbol_map.json").unwrap()).unwrap();
    
    // Convert to our Symbol format
    let mut symbol_map = HashMap::new();
    for (name, data) in symbol_map_json {
        if let (Some(symbol_type), Some(source_file), Some(crate_name)) = (
            data["symbol_type"].as_str(),
            data["source_file"].as_str(), 
            data["crate_name"].as_str()
        ) {
            let dependencies = data["dependencies"].as_array()
                .map(|arr| arr.iter().filter_map(|v| v.as_str().map(|s| s.to_string())).collect())
                .unwrap_or_default();
                
            symbol_map.insert(name.clone(), split_decls_genesis::Symbol {
                name: name.clone(),
                symbol_type: symbol_type.to_string(),
                source_file: source_file.to_string(),
                crate_name: crate_name.to_string(),
                dependencies,
            });
        }
    }
    
    println!("✅ Loaded {} symbols", symbol_map.len());
    
    // Find rustc_driver main function
    let rustc_driver_main = symbol_map.iter()
        .find(|(name, symbol)| {
            name.as_str() == "main" && symbol.crate_name == "rustc_driver"
        });
    
    match rustc_driver_main {
        Some((name, symbol)) => {
            println!("\n🎯 FOUND RUSTC_DRIVER::MAIN:");
            println!("  Function: {}", name);
            println!("  Type: {}", symbol.symbol_type);
            println!("  File: {}", symbol.source_file);
            println!("  Dependencies: {}", symbol.dependencies.len());
            
            // Analyze dependencies (ignore jemalloc and macos branches)
            println!("\n🔍 DEPENDENCY ANALYSIS (ignoring jemalloc/macos):");
            let mut resolved = 0;
            let mut unresolved = 0;
            
            for (i, dep) in symbol.dependencies.iter().enumerate() {
                // Skip jemalloc and macos-specific dependencies
                if dep.contains("jemalloc") || dep.contains("macos") || dep.contains("_rjem_") {
                    continue;
                }
                
                // Try to resolve
                match resolve_qualified_dependency(dep, &symbol_map) {
                    Some(location) => {
                        resolved += 1;
                        println!("  {}. ✅ {} → {}", i+1, dep, location);
                    },
                    None => {
                        unresolved += 1;
                        println!("  {}. ❌ {} (unresolved)", i+1, dep);
                        
                        // Analyze what it is
                        if dep.starts_with("attr_") {
                            println!("       → Attribute dependency");
                        } else if dep.contains("::") {
                            println!("       → Qualified path (needs resolution)");
                        } else if dep.starts_with("target_") {
                            println!("       → Cfg attribute (compile-time)");
                        } else {
                            println!("       → Type/primitive reference");
                        }
                    }
                }
            }
            
            println!("\n📊 RUSTC_DRIVER::MAIN RESOLUTION:");
            println!("  ✅ Resolved: {}", resolved);
            println!("  ❌ Unresolved: {}", unresolved);
            println!("  📈 Resolution rate: {:.1}%", (resolved as f64 / (resolved + unresolved) as f64) * 100.0);
            
            // Trace deeper - find what rustc_driver::main calls
            println!("\n🌊 TRACING DEEPER INTO RUSTC_DRIVER:");
            trace_rustc_driver_dependencies(&symbol_map);
            
        },
        None => {
            println!("❌ rustc_driver::main not found");
            
            // Show what rustc_driver symbols we have
            let rustc_driver_symbols: Vec<_> = symbol_map.iter()
                .filter(|(_, symbol)| symbol.crate_name == "rustc_driver")
                .collect();
            
            println!("📋 Available rustc_driver symbols ({}):", rustc_driver_symbols.len());
            for (name, symbol) in rustc_driver_symbols.iter().take(10) {
                println!("  - {} ({})", name, symbol.symbol_type);
            }
        }
    }
}

fn trace_rustc_driver_dependencies(symbol_map: &HashMap<String, split_decls_genesis::Symbol>) {
    // Find key rustc_driver functions
    let key_functions = vec!["run_compiler", "compile", "handle_options"];
    
    for func_name in key_functions {
        if let Some(symbol) = symbol_map.iter()
            .find(|(name, sym)| name.as_str() == func_name && sym.crate_name == "rustc_driver")
            .map(|(_, sym)| sym) {
            
            println!("  🔧 {}: {} (deps: {})", func_name, symbol.symbol_type, symbol.dependencies.len());
            
            // Show first few dependencies
            for dep in symbol.dependencies.iter().take(5) {
                if !dep.contains("jemalloc") && !dep.contains("macos") {
                    println!("    - {}", dep);
                }
            }
        }
    }
}
